/* Xidecode :: Guía 8 · JSON, localStorage y sessionStorage */
(function () {
  var H = JT.H, C = JT.C, J = JT.J, eq = JT.eq, all = JT.all;

  JT.topics.push({
    id: 'g8', num: 8, guide: 'Guía 8', title: 'JSON, localStorage y sessionStorage', short: 'JSON y Storage', color: '#e5c07b', storage: true,
    summary: 'Convierte objetos en texto con JSON y guarda datos en el navegador para que no se pierdan al recargar la página.',

    theory: [
      { icon: 'db', h: '¿Qué es JSON?', html: '<p><b>JSON</b> es una manera de escribir datos como <b>texto</b>, usando la misma forma que los objetos de JavaScript: llaves <code>{ }</code> para objetos y corchetes <code>[ ]</code> para listas. Es el formato que usan casi todas las páginas para hablar con un servidor.</p><p>Cada valor puede ser un texto, un número, <code>true</code>, <code>false</code>, <code>null</code>, otro objeto o una lista.</p>', analogy: 'Un objeto de JavaScript es una <b>ficha de papel</b> que solo existe dentro de tu programa. JSON es esa misma ficha <b>escrita a máquina</b> en una carta: así puede viajar o guardarse.', code: '{\n  "nombre": "Ana",\n  "edad": 20,\n  "materias": ["Web", "Bases"],\n  "activa": true\n}' },
      { icon: 'refresh', h: 'stringify y parse: ida y vuelta', html: '<p>JavaScript trae dos funciones para pasar de un lado a otro:</p><ul><li><code>JSON.stringify(objeto)</code>: <b>objeto → texto</b> JSON.</li><li><code>JSON.parse(texto)</code>: <b>texto → objeto</b>.</li></ul><p><code>stringify</code> acepta un <b>reemplazador</b> (filtra o modifica propiedades) y un <b>separador</b> (sangría para que se lea mejor). <code>parse</code> acepta un <b>transformador</b> que puede cambiar valores o quitar propiedades al leer.</p>', analogy: '<b>stringify</b> es meter tus cosas en cajas para la mudanza. <b>parse</b> es desempacarlas en la casa nueva.', code: 'var texto = JSON.stringify({ a: 1 }); // \'{"a":1}\'\nvar objeto = JSON.parse(texto);       // { a: 1 }' },
      { icon: 'alert', h: 'Reglas estrictas de JSON', html: '<p>JSON es más estricto que un objeto de JavaScript. Por eso <code>JSON.parse</code> falla si el texto tiene:</p><ul><li>Comillas <b>simples</b> en vez de dobles.</li><li>Claves <b>sin comillas</b>.</li><li>Una <b>coma</b> sobrante al final.</li><li>Comentarios, <code>undefined</code> o funciones.</li></ul><p>Cuando el texto viene de fuera (usuario, servidor, almacenamiento) conviene usar <code>try / catch</code>.</p>', code: '// MAL  (no es JSON):\n{ nombre: \'Ana\', }\n// BIEN:\n{ "nombre": "Ana" }' },
      { icon: 'lock', h: 'localStorage: la mochila del navegador', html: '<p><b>localStorage</b> guarda pares <code>clave / valor</code> en la computadora del usuario. Los datos <b>no caducan</b>: siguen ahí aunque cierres la pestaña o el navegador. Caben unos <b>5 MB</b> por sitio y todas las páginas de un mismo sitio los comparten.</p><p>A diferencia de las cookies, no viajan al servidor en cada petición.</p>', analogy: 'Es un <b>cuaderno</b> que el navegador guarda para tu sitio. Lo que escribes ahí sigue estando mañana.', code: 'localStorage.setItem("nombre", "Ana");\nvar quien = localStorage.getItem("nombre"); // "Ana"' },
      { icon: 'flag', h: 'sessionStorage: la nota adhesiva', html: '<p><b>sessionStorage</b> funciona igual pero los datos viven solo durante la <b>sesión</b> de esa pestaña. Al cerrarla, se borran. Cada pestaña tiene el suyo, aunque abran el mismo sitio.</p><table><tr><th></th><th>localStorage</th><th>sessionStorage</th></tr><tr><td>Dura</td><td>Hasta que lo borres</td><td>Hasta cerrar la pestaña</td></tr><tr><td>Se comparte entre pestañas</td><td>Sí</td><td>No</td></tr></table>', analogy: 'localStorage es el <b>cuaderno</b>. sessionStorage es una <b>nota adhesiva</b> que se tira al terminar la clase.' },
      { icon: 'code', h: 'Los métodos del almacenamiento', html: '<ul><li><code>setItem(clave, valor)</code>: guarda.</li><li><code>getItem(clave)</code>: lee (o <code>null</code> si no existe).</li><li><code>removeItem(clave)</code>: borra una clave.</li><li><code>clear()</code>: borra todo.</li><li><code>key(n)</code>: nombre de la clave en la posición n.</li><li><code>length</code>: cuántos datos hay.</li></ul><p>Además de la API puedes usar <b>notación de arreglo</b> <code>localStorage["clave"]</code> o de <b>propiedad</b> <code>localStorage.clave</code>.</p>', code: 'localStorage.setItem("a", "1");  // API\nlocalStorage["a"] = "1";         // notación de arreglo\nlocalStorage.a = "1";            // propiedad' },
      { icon: 'layers', h: 'Guardar objetos y listas', html: '<p>El almacenamiento <b>solo guarda texto</b>. Si guardas un número lo recuperas como texto, y si guardas un objeto obtienes <code>"[object Object]"</code>. La receta es siempre la misma:</p><ol><li>Al guardar: <code>JSON.stringify(dato)</code>.</li><li>Al leer: <code>JSON.parse(texto)</code>.</li></ol><p>Cuando otra pestaña cambia el almacenamiento, tu página recibe el evento <code>storage</code>.</p>', code: 'var lista = ["pan", "leche"];\nlocalStorage.setItem("compras", JSON.stringify(lista));\nvar leida = JSON.parse(localStorage.getItem("compras"));' }
    ],

    examples: [
      /* 1 */
      { id: 'g8e1', title: 'De objeto a texto: JSON.stringify', short: 'Convierte un objeto en un texto JSON',
        intro: '<p>Un objeto vive solo dentro de tu programa. Para guardarlo o enviarlo necesitas <b>texto</b>. <code>JSON.stringify</code> hace esa conversión. En este ejemplo creamos un objeto <code>alumno</code>, lo convertimos y lo mostramos en la página.</p>',
        parts: [
          H('<h3>Convertir un objeto en texto JSON</h3>\n<pre id="salida"></pre>', 'La etiqueta <code>&lt;pre&gt;</code> respeta los espacios y saltos de línea; ahí mostraremos el resultado. Le damos un <code>id</code> para encontrarla desde JavaScript.'),
          J('var alumno = {\n  nombre: "Ana",\n  edad: 20,\n  materias: ["Web", "Bases de datos"],\n  activo: true\n};', 'Esto es un <b>objeto de JavaScript</b>: pares <code>clave: valor</code> entre llaves. Mezcla un texto, un número, una lista y un booleano.'),
          J('var texto = JSON.stringify(alumno);', '<code>JSON.stringify</code> recibe el objeto y devuelve un <b>texto</b> con formato JSON. Guardamos ese texto en la variable <code>texto</code>.'),
          J('console.log(typeof alumno); // object\nconsole.log(typeof texto);  // string', '<code>typeof</code> dice el tipo. El objeto original sigue siendo <code>object</code>, pero el resultado es un <code>string</code> (texto). Mira la pestaña Consola bajo la pantalla.'),
          J('document.getElementById("salida").textContent = texto;', 'Buscamos el <code>&lt;pre&gt;</code> por su id y escribimos el texto dentro. Fíjate cómo las claves ahora llevan <b>comillas dobles</b>: eso es JSON.')
        ],
        notes: [{ type: 'tip', html: 'El texto resultante es una sola línea. En el siguiente ejemplo verás cómo hacerlo más legible.' }],
        tryit: ['Cambia la edad y agrega otra propiedad, por ejemplo <code>ciudad: "Santa Ana"</code>.', 'Agrega una propiedad que sea una función: <code>saludar: function () {}</code>. ¿Aparece en el texto? (Las funciones se omiten.)', 'Cambia <code>activo: true</code> por <code>activo: undefined</code> y observa.'] },
      /* 2 */
      { id: 'g8e2', title: 'stringify con separador y reemplazador', short: 'JSON legible y filtrado de propiedades',
        intro: '<p><code>JSON.stringify(objeto, reemplazador, separador)</code> tiene tres parámetros. El <b>separador</b> (por ejemplo <code>2</code>) indenta el resultado para leerlo mejor. El <b>reemplazador</b> puede ser una lista de propiedades permitidas o una función que decide qué dato se incluye. Útil para <b>no guardar contraseñas</b>.</p>',
        parts: [
          H('<h3>1. Con separador (2 espacios)</h3>\n<pre id="a"></pre>\n<h3>2. Solo ciertas propiedades</h3>\n<pre id="b"></pre>\n<h3>3. Ocultando la clave</h3>\n<pre id="c"></pre>', 'Tres cajas <code>&lt;pre&gt;</code> para comparar las tres formas.'),
          J('var usuario = {\n  nombre: "Luis",\n  edad: 31,\n  clave: "secreta123"\n};', 'Un usuario con un dato sensible: <code>clave</code>.'),
          J('var bonito = JSON.stringify(usuario, null, 2);', 'El segundo parámetro es <code>null</code> (sin reemplazador) y el tercero es <code>2</code>: <b>dos espacios</b> de sangría por nivel.'),
          J('var solo = JSON.stringify(usuario, ["nombre", "edad"]);', 'Si el reemplazador es una <b>lista</b>, solo se incluyen las propiedades cuyo nombre esté en ella. <code>clave</code> queda fuera.'),
          J('var sinClave = JSON.stringify(usuario, function (clave, valor) {\n  if (clave === "clave") {\n    return undefined;\n  }\n  return valor;\n}, 2);', 'Con una <b>función</b> decides propiedad por propiedad. Si devuelves <code>undefined</code>, esa propiedad se omite; si devuelves <code>valor</code>, se incluye tal cual.'),
          J('document.getElementById("a").textContent = bonito;\ndocument.getElementById("b").textContent = solo;\ndocument.getElementById("c").textContent = sinClave;', 'Mostramos cada resultado en su caja.')
        ],
        notes: [{ type: 'info', html: 'Recuerda: el parámetro <b>reemplazador</b> de <code>stringify</code> es la contraparte del <b>transformador</b> de <code>parse</code>, que verás en el ejemplo 4.' }],
        tryit: ['Cambia el <code>2</code> por <code>4</code> o por <code>"--"</code> (¡también acepta texto como separador!).', 'En la lista de propiedades deja solo <code>"nombre"</code>.'] },
      /* 3 */
      { id: 'g8e3', title: 'De texto a objeto: JSON.parse', short: 'Lee un texto JSON y usa sus datos',
        intro: '<p>Cuando recibes datos (de un servidor o del almacenamiento) llegan como <b>texto</b>. Con <code>JSON.parse</code> los conviertes en un objeto y ya puedes usar el punto: <code>persona.nombre</code>.</p>',
        parts: [
          H('<h3 id="titulo">Resultado</h3>\n<p id="ficha"></p>', 'Un título y un párrafo vacío donde pondremos la ficha.'),
          J('var texto = \'{"nombre":"Luis","edad":31,"ciudad":"Santa Ana"}\';', 'Este <b>texto</b> está escrito en formato JSON. Lo envolvemos con comillas simples porque adentro hay comillas dobles.'),
          J('var persona = JSON.parse(texto);', '<code>JSON.parse</code> lee el texto y devuelve un <b>objeto</b> de JavaScript con las mismas claves.'),
          J('console.log(persona.nombre);  // Luis\nconsole.log(persona.edad + 1);  // 32', 'Ahora las propiedades se leen con punto. Como <code>edad</code> es un número real (no un texto), incluso se puede sumar.'),
          J('document.getElementById("ficha").textContent =\n  persona.nombre + " tiene " + persona.edad + " años y vive en " + persona.ciudad + ".";', 'Armamos una frase uniendo textos y datos con <code>+</code> y la escribimos en el párrafo.')
        ],
        notes: [{ type: 'warn', html: 'Si el texto no cumple las reglas de JSON, <code>parse</code> lanza un error. Lo manejaremos en el ejemplo 5.' }],
        tryit: ['Agrega una propiedad nueva en el texto, por ejemplo <code>"profesion":"Ingeniero"</code>, y muéstrala en la frase.', 'Cambia las comillas dobles internas por comillas simples y mira el error que explica el cuadro rojo.'] },
      /* 4 */
      { id: 'g8e4', title: 'El transformador de JSON.parse', short: 'Modifica o elimina datos mientras se leen',
        intro: '<p><code>JSON.parse(texto, transformador)</code> acepta una función que se llama <b>por cada propiedad</b> antes de guardarla en el objeto. Sirve para convertir textos en fechas o para descartar datos que no quieres. Si la función devuelve <code>undefined</code>, esa propiedad <b>se elimina</b>.</p>',
        parts: [
          H('<h3>Resultado</h3>\n<pre id="salida"></pre>', 'Una caja para ver el resultado.'),
          J('var texto = \'{"nombre":"Marta","ingreso":"2021-03-15","clave":"1234","edad":27}\';', 'Un JSON con una <b>fecha como texto</b> y una <b>clave</b> que no queremos conservar.'),
          J('var persona = JSON.parse(texto, function (clave, valor) {\n  if (clave === "ingreso") {\n    return new Date(valor);\n  }\n  if (clave === "clave") {\n    return undefined;\n  }\n  return valor;\n});', 'La función recibe cada <code>clave</code> y su <code>valor</code>. Si es <code>ingreso</code>, la convierte en un objeto <code>Date</code>. Si es <code>clave</code>, devuelve <code>undefined</code> y se descarta. Para todo lo demás devuelve <code>valor</code> sin cambios.'),
          J('var linea1 = "Año de ingreso: " + persona.ingreso.getFullYear();\nvar linea2 = "¿Tiene clave? " + ("clave" in persona);', 'Como <code>ingreso</code> ahora es una fecha, podemos usar <code>getFullYear()</code>. El operador <code>in</code> comprueba si existe una propiedad: dará <code>false</code>.'),
          J('document.getElementById("salida").textContent = linea1 + "\\n" + linea2;', '<code>\\n</code> es un salto de línea dentro de un texto.')
        ],
        tryit: ['Haz que <code>edad</code> se devuelva multiplicada por 2 dentro del transformador.', 'Quita el <code>return valor;</code> del final y observa qué pasa con las demás propiedades (¡desaparecen!).'] },
      /* 5 */
      { id: 'g8e5', title: 'JSON inválido y try / catch', short: 'Detecta textos que no son JSON válido',
        intro: '<p>Un texto con comillas simples, una clave sin comillas o una coma sobrante <b>no es JSON</b> y hace que <code>JSON.parse</code> lance un error. Con <code>try / catch</code> puedes capturarlo en vez de romper el programa. Aquí probamos cuatro textos.</p>',
        parts: [
          H('<h3>Pruebas de JSON.parse</h3>\n<ul id="lista"></ul>', 'Una lista donde iremos mostrando el resultado de cada prueba.'),
          J('function leer(texto) {\n  try {\n    var objeto = JSON.parse(texto);\n    return "Válido: nombre = " + objeto.nombre;\n  } catch (e) {\n    return "Error: " + e.message;\n  }\n}', 'La función intenta parsear. Si todo va bien, devuelve el resultado; si <code>parse</code> falla, el control salta al <code>catch</code> y <code>e.message</code> trae la explicación del navegador.'),
          J('var pruebas = [\n  \'{"nombre":"Ana"}\',\n  "{\'nombre\':\'Ana\'}",\n  \'{nombre:"Ana"}\',\n  \'{"nombre":"Ana",}\'\n];', 'Cuatro textos: el primero es válido. El segundo usa comillas simples, el tercero una clave sin comillas y el cuarto una coma sobrante.'),
          J('var lista = document.getElementById("lista");\nfor (var i = 0; i < pruebas.length; i++) {\n  lista.innerHTML += "<li><code>" + pruebas[i].replace(/</g, "&lt;") + "</code> → " + leer(pruebas[i]) + "</li>";\n}', 'Recorremos las pruebas con un bucle <code>for</code> y agregamos un <code>&lt;li&gt;</code> por cada una con el texto original y su resultado.')
        ],
        notes: [{ type: 'tip', html: 'En JSON: <b>comillas dobles</b> siempre, claves entre comillas, sin comas finales, sin comentarios.' }],
        tryit: ['Agrega una quinta prueba válida con dos propiedades.', 'Prueba con un texto vacío <code>""</code> y lee el mensaje de error.'] },
      /* 6 */
      { id: 'g8e6', title: 'Lista de personas desde un arreglo JSON', short: 'Construye tarjetas a partir de datos',
        intro: '<p>Este es el ejemplo de la guía (<code>names.js</code>): un <b>arreglo de objetos</b> guarda los datos de varias personas y una función los convierte en tarjetas HTML. Es el patrón más común al trabajar con JSON: <b>datos → HTML</b>.</p>',
        parts: [
          H('<h2 class="titulo">Datos personales con JSON</h2>\n<div id="info"></div>', 'Un título y un contenedor <code>div</code> vacío donde se volcarán las tarjetas.'),
          C('.titulo { color: #b72231; text-align: center; }\n.grid { display: flex; flex-wrap: wrap; gap: 12px; padding: 0; list-style: none; }\n.box { width: 170px; border-radius: 10px; padding: 14px; background: #fdf0f2; border: 1px solid #efc5ca; }\n.avatar { width: 54px; height: 54px; border-radius: 50%; background: #d24b5a; color: #fff; display: grid; place-items: center; font-weight: 700; font-size: 20px; margin-bottom: 8px; }\n.box h4 { margin: 0 0 4px; }\n.box p { margin: 0; font-size: 14px; }', 'Estilos para las tarjetas: se acomodan con <code>flex</code>, tienen esquinas redondeadas y un círculo de color con la inicial de la persona (en lugar de una foto).'),
          J('var nombres = {\n  "Personas": [\n    { "nombre": "Juan", "apellido": "Robles", "edad": 29, "profesion": "Licenciado" },\n    { "nombre": "Lilian", "apellido": "Rosales", "edad": 27, "profesion": "Bachiller" },\n    { "nombre": "Gustavo", "apellido": "Gonzalez", "edad": 28, "profesion": "Arquitecto" },\n    { "nombre": "Génesis", "apellido": "Deras", "edad": 31, "profesion": "Mercadóloga" }\n  ]\n};', 'El objeto <code>nombres</code> tiene una propiedad <code>Personas</code> que es un <b>arreglo</b> de objetos. Cada objeto es una persona.'),
          J('function volcarDatos(datos) {\n  var total = datos.length;\n  var html = "<ul class=\\"grid\\">";\n  for (var i = 0; i < total; i++) {\n    html += "<li class=\\"box\\">";\n    html += "<div class=\\"avatar\\">" + datos[i].nombre.charAt(0) + "</div>";\n    html += "<h4>" + datos[i].nombre + " " + datos[i].apellido + "</h4>";\n    html += "<p>Edad: " + datos[i].edad + "<br>Profesión: " + datos[i].profesion + "</p>";\n    html += "</li>";\n  }\n  html += "</ul>";\n  return html;\n}', 'La función recorre el arreglo con <code>for</code> y va <b>acumulando</b> un texto HTML con <code>+=</code>. <code>datos[i].nombre</code> significa "la propiedad nombre del objeto en la posición i". Las comillas dobles dentro del texto se escriben <code>\\"</code>.'),
          J('var div = document.getElementById("info");\ndiv.innerHTML = volcarDatos(nombres.Personas);', 'Llamamos a la función pasándole el arreglo <code>nombres.Personas</code> y metemos el HTML resultante dentro del div.')
        ],
        tryit: ['Agrega una quinta persona al arreglo.', 'Cambia el color del círculo en el CSS (<code>.avatar</code>).', 'Muestra también el apellido en el círculo con <code>datos[i].apellido.charAt(0)</code>.'] },
      /* 7 */
      { id: 'g8e7', title: 'localStorage: guardar, leer y borrar', short: 'Un dato que sobrevive a recargar la página',
        intro: '<p>Escribe algo, pulsa <b>Guardar</b> y luego usa el botón <b>Recargar</b> de la computadora (o cierra y abre la pantalla): el dato <b>sigue ahí</b>. Es el ejercicio 2 de la guía.</p>',
        parts: [
          H('<p id="mensaje"></p>\n<label for="dato">Ingrese el dato:</label>\n<input type="text" id="dato">\n<br><br>\n<button id="guardar">Guardar</button>\n<button id="borrar">Borrar</button>\n<p id="soporte"></p>', 'Un párrafo para mensajes, un campo de texto, dos botones y un párrafo para indicar si el navegador soporta almacenamiento.'),
          J('if (typeof localStorage == "undefined") {\n  document.getElementById("soporte").textContent = "Tu navegador no soporta almacenamiento local.";\n} else {\n  document.getElementById("soporte").textContent = "¡Tu navegador soporta almacenamiento local!";\n}', '<code>typeof</code> comprueba si <code>localStorage</code> existe. En navegadores muy viejos sería <code>"undefined"</code>.'),
          J('var mensaje = document.getElementById("mensaje");\nvar caja = document.getElementById("dato");\nvar guardado = localStorage.getItem("miDato");', 'Guardamos en variables los elementos que usaremos y <b>leemos</b> lo que hubiera guardado antes con la clave <code>"miDato"</code>. Si no hay nada, <code>getItem</code> devuelve <code>null</code>.'),
          J('if (guardado != null) {\n  mensaje.textContent = "Dato cargado: " + guardado;\n  caja.value = guardado;\n}', 'Si <b>sí</b> había algo guardado, lo mostramos y lo volvemos a poner en el campo. Esto ocurre cada vez que se carga la página.'),
          J('document.getElementById("guardar").onclick = function () {\n  var limpio = caja.value.replace(/<\\/?[^>]+>/gi, "");\n  localStorage.setItem("miDato", limpio);\n  mensaje.textContent = "Se guardó: " + limpio;\n};', 'Al pulsar Guardar: primero <b>limpiamos</b> el texto quitando etiquetas HTML (por seguridad) con una expresión regular, y luego lo guardamos con <code>setItem(clave, valor)</code>.'),
          J('document.getElementById("borrar").onclick = function () {\n  localStorage.clear();\n  caja.value = "";\n  mensaje.textContent = "Almacenamiento local liberado.";\n};', '<code>localStorage.clear()</code> borra <b>todos</b> los datos del sitio. Para borrar solo una clave usarías <code>removeItem("miDato")</code>.')
        ],
        notes: [{ type: 'info', html: 'Fíjate en la pestaña <b>Almacenamiento</b> bajo la pantalla: ahí ves la clave y el valor como en las herramientas de desarrollador del navegador.' }],
        tryit: ['Cambia <code>clear()</code> por <code>removeItem("miDato")</code> en el botón Borrar.', 'Cambia <code>localStorage</code> por <code>sessionStorage</code> y prueba "Cerrar pestaña" en la computadora.'] },
      /* 8 */
      { id: 'g8e8', title: 'Tres formas de usar localStorage', short: 'API, notación de arreglo y propiedad',
        intro: '<p>Hay tres maneras equivalentes de guardar y leer: con los <b>métodos</b> de la API, con <b>corchetes</b> como si fuera un arreglo, o con <b>punto</b> como si fuera un objeto. Elige una en el menú y pulsa Seleccionar.</p>',
        parts: [
          H('<select id="metodo">\n  <option value="api">API localStorage</option>\n  <option value="array">Notación de arreglo</option>\n  <option value="object">Propiedades de objeto</option>\n</select>\n<button id="probar">Seleccionar</button>\n<div id="contenido"></div>', 'Un menú desplegable con las tres formas, un botón y un contenedor para el resultado.'),
          J('var valor;\n\nfunction mostrar() {\n  var opcion = document.getElementById("metodo").value;', 'Declaramos <code>valor</code> fuera de la función y, dentro, leemos qué opción eligió el usuario con <code>.value</code> del select.'),
          J('  switch (opcion) {\n    case "api":\n      localStorage.setItem("bienvenida", "Hola con la API");\n      valor = localStorage.getItem("bienvenida");\n      break;', '<code>switch</code> elige qué bloque ejecutar. En el caso <code>"api"</code> usamos <code>setItem</code> y <code>getItem</code>. El <code>break</code> evita que siga con el siguiente caso.'),
          J('    case "array":\n      localStorage["bienvenida"] = "Hola con notación de arreglo";\n      valor = localStorage["bienvenida"];\n      break;\n    case "object":\n      localStorage.bienvenida = "Hola con propiedades de objeto";\n      valor = localStorage.bienvenida;\n      break;\n    default:\n      alert("Esta opción no existe");\n      break;\n  }', 'En <code>"array"</code> se usan corchetes y en <code>"object"</code> el punto. Las tres escriben y leen la <b>misma clave</b> <code>bienvenida</code>. <code>default</code> se ejecuta si ningún caso coincide.'),
          J('  document.getElementById("contenido").innerHTML = "<p>Usando <b>" + opcion + "</b>: " + valor + "</p>";\n}\n\ndocument.getElementById("probar").onclick = mostrar;', 'Mostramos el resultado, cerramos la función con <code>}</code> y la conectamos al botón. Fíjate que escribimos <code>mostrar</code> <b>sin paréntesis</b>: pasamos la función, no la ejecutamos.')
        ],
        notes: [{ type: 'tip', html: 'La notación de punto es cómoda pero falla si la clave tiene espacios o guiones; ahí usa corchetes o la API.' }],
        tryit: ['Agrega una cuarta opción al select y su <code>case</code>.', 'Cambia el valor guardado en cada caso.'] },
      /* 9 */
      { id: 'g8e9', title: 'length, key() y recorrer todo lo guardado', short: 'Lista todos los datos del almacenamiento',
        intro: '<p><code>localStorage.length</code> dice cuántos datos hay y <code>localStorage.key(i)</code> da el nombre de la clave en la posición <code>i</code>. Con un bucle <code>for</code> puedes <b>listar todo</b> o borrar todo lo guardado.</p>',
        parts: [
          H('<button id="crear">Crear datos de ejemplo</button>\n<button id="listar">Listar</button>\n<button id="quitar">Quitar "color"</button>\n<p id="cuantos"></p>\n<ul id="lista"></ul>', 'Tres botones y dos zonas para mostrar la cantidad y la lista.'),
          J('document.getElementById("crear").onclick = function () {\n  localStorage.setItem("nombre", "Ana");\n  localStorage.setItem("color", "azul");\n  localStorage.setItem("nivel", "3");\n  listar();\n};', 'Guarda tres datos de ejemplo y luego llama a <code>listar()</code> (que definimos más abajo; las funciones declaradas con <code>function</code> pueden usarse antes).'),
          J('function listar() {\n  var ul = document.getElementById("lista");\n  ul.innerHTML = "";\n  document.getElementById("cuantos").textContent = "Datos guardados: " + localStorage.length;', 'Primero vaciamos la lista y mostramos <code>localStorage.length</code>, la cantidad de pares guardados.'),
          J('  for (var i = 0; i < localStorage.length; i++) {\n    var clave = localStorage.key(i);\n    ul.innerHTML += "<li>" + clave + " = " + localStorage.getItem(clave) + "</li>";\n  }\n}', 'El bucle va de 0 hasta <code>length - 1</code>. En cada vuelta <code>key(i)</code> da la clave y <code>getItem(clave)</code> su valor.'),
          J('document.getElementById("listar").onclick = listar;\n\ndocument.getElementById("quitar").onclick = function () {\n  localStorage.removeItem("color");\n  listar();\n};\n\nlistar();', '<code>removeItem("color")</code> borra solo esa clave (si no existe, no hace nada). La última línea muestra la lista al cargar la página.')
        ],
        notes: [{ type: 'info', html: 'Con este mismo bucle, si dentro llamas a <code>removeItem(clave)</code> tendrías un "borrar todo uno por uno". Cuidado: al borrar, <code>length</code> cambia mientras recorres.' }],
        tryit: ['Agrega un cuarto dato en "Crear datos de ejemplo".', 'Haz un botón que borre todo con <code>localStorage.clear()</code>.'] },
      /* 10 */
      { id: 'g8e10', title: 'Guardar objetos y arreglos', short: 'stringify al guardar y parse al leer',
        intro: '<p>Es el ejemplo de la guía (<code>appform.js</code>): guarda un <b>dato simple</b>, un <b>objeto</b> y un <b>arreglo de objetos</b>. Para objetos y arreglos hace falta convertirlos a texto con <code>JSON.stringify</code> y recuperarlos con <code>JSON.parse</code>.</p>',
        parts: [
          H('<label>Nombre: <input type="text" id="name" placeholder="Su nombre"></label>\n<label>Edad: <input type="number" id="age" placeholder="Su edad"></label>\n<br><br>\n<button id="bSave">Guardar objeto</button>\n<button id="bRestore">Restaurar objeto</button>\n<button id="bAdd">Agregar a arreglo</button>\n<button id="bList">Restaurar arreglo</button>\n<button id="bClear">Limpiar</button>\n<div id="state" class="estado"></div>', 'Dos campos y cinco botones. El div <code>state</code> mostrará lo que se restaure.'),
          C('.estado { margin-top: 12px; background: #3b82c4; color: #fff; padding: 10px; border-radius: 8px; min-height: 22px; }\nlabel { margin-right: 10px; }', 'Un recuadro azul para los mensajes de estado.'),
          J('var nombre = document.getElementById("name");\nvar edad = document.getElementById("age");\nvar estado = document.getElementById("state");\nvar personas = [];', 'Variables con los elementos y un arreglo vacío <code>personas</code> que iremos llenando.'),
          J('document.getElementById("bSave").onclick = function () {\n  var persona = new Object();\n  persona.name = nombre.value;\n  persona.age = edad.value;\n  localStorage.setItem("person", JSON.stringify(persona));\n  estado.textContent = "Objeto guardado.";\n};', 'Creamos un objeto con <code>new Object()</code>, le agregamos propiedades y lo guardamos <b>convertido a texto</b> con <code>JSON.stringify</code>. Sin stringify se guardaría <code>[object Object]</code>.'),
          J('document.getElementById("bRestore").onclick = function () {\n  var persona = JSON.parse(localStorage.getItem("person"));\n  if (persona) {\n    nombre.value = persona.name;\n    edad.value = persona.age;\n    estado.textContent = "Nombre: " + persona.name + ", Edad: " + persona.age;\n  } else {\n    estado.textContent = "Aún no hay un objeto guardado.";\n  }\n};', '<code>getItem</code> devuelve el texto y <code>JSON.parse</code> lo vuelve objeto. Si nunca se guardó nada, <code>getItem</code> da <code>null</code>; <code>JSON.parse(null)</code> da <code>null</code>, por eso el <code>if (persona)</code>.'),
          J('document.getElementById("bAdd").onclick = function () {\n  personas.push({ name: nombre.value, age: parseInt(edad.value) });\n  localStorage.setItem("persons", JSON.stringify(personas));\n  estado.textContent = "Arreglo con " + personas.length + " persona(s) guardado.";\n};', '<code>push</code> agrega un objeto al final del arreglo y luego guardamos <b>todo el arreglo</b> convertido a texto. <code>parseInt</code> convierte la edad (texto) en número.'),
          J('document.getElementById("bList").onclick = function () {\n  var lista = JSON.parse(localStorage.getItem("persons")) || [];\n  estado.innerHTML = "";\n  for (var i = 0; i < lista.length; i++) {\n    estado.innerHTML += "<p>Nombre: " + lista[i].name + ", Edad: " + lista[i].age + "</p>";\n  }\n};\n\ndocument.getElementById("bClear").onclick = function () {\n  localStorage.clear();\n  estado.textContent = "";\n};', 'Recuperamos el arreglo y lo recorremos. <code>|| []</code> significa "si no hay nada, usa un arreglo vacío" y evita errores.')
        ],
        notes: [{ type: 'warn', html: 'Prueba pulsar <b>Restaurar objeto</b> antes de guardar nada: el programa lo maneja con el <code>if</code>. Luego quita el <code>JSON.stringify</code> del guardado y mira el error que aparece al restaurar.' }],
        tryit: ['Agrega 3 personas al arreglo y pulsa Restaurar arreglo; luego recarga la pantalla y vuelve a restaurar.', 'Guarda un tercer tipo de dato: un número con <code>localStorage.setItem("n", 5)</code> y comprueba con <code>typeof</code> qué devuelve getItem.'] },
      /* 11 */
      { id: 'g8e11', title: 'sessionStorage vs localStorage', short: 'Dos contadores que se comportan distinto',
        intro: '<p>Dos contadores: uno en <b>localStorage</b> y otro en <b>sessionStorage</b>. Súmales algunos clics y luego prueba los botones de la computadora: <b>Recargar</b> (ambos se conservan) y <b>Cerrar pestaña</b> (sessionStorage se borra, localStorage permanece).</p>',
        parts: [
          H('<p>Contador en <b>localStorage</b>: <span id="cl">0</span> <button id="sl">+1</button></p>\n<p>Contador en <b>sessionStorage</b>: <span id="cs">0</span> <button id="ss">+1</button></p>', 'Dos contadores con su botón de sumar.'),
          J('function leer(almacen, clave) {\n  var v = parseInt(almacen.getItem(clave));\n  return isNaN(v) ? 0 : v;\n}', 'Función auxiliar: lee un número de <b>cualquier</b> almacén (<code>localStorage</code> o <code>sessionStorage</code>), porque los dos tienen los mismos métodos. Si no hay nada, <code>parseInt(null)</code> da <code>NaN</code> y devolvemos 0.'),
          J('var cl = document.getElementById("cl");\nvar cs = document.getElementById("cs");\ncl.textContent = leer(localStorage, "contador");\ncs.textContent = leer(sessionStorage, "contador");', 'Al cargar, mostramos lo que haya guardado en cada almacén.'),
          J('document.getElementById("sl").onclick = function () {\n  var n = leer(localStorage, "contador") + 1;\n  localStorage.setItem("contador", n);\n  cl.textContent = n;\n};\n\ndocument.getElementById("ss").onclick = function () {\n  var n = leer(sessionStorage, "contador") + 1;\n  sessionStorage.setItem("contador", n);\n  cs.textContent = n;\n};', 'Cada botón lee su valor, le suma 1, lo guarda otra vez y lo muestra. El código es idéntico; solo cambia el almacén.')
        ],
        notes: [{ type: 'tip', html: 'Resumen: <b>localStorage</b> = preferencias que deben quedarse. <b>sessionStorage</b> = datos temporales de una visita (formulario a medias, carrito de la sesión).' }],
        tryit: ['Suma 3 en cada uno, pulsa <b>Cerrar pestaña</b> y luego <b>Recargar</b>.', 'Agrega un tercer botón "Reiniciar" que ponga ambos contadores en 0.'] },
      /* 12 */
      { id: 'g8e12', title: 'El evento storage', short: 'Reacciona cuando otra pestaña cambia los datos',
        intro: '<p>Cuando <b>otra pestaña</b> del mismo sitio cambia el almacenamiento, tu página recibe el evento <code>storage</code> con la clave, el valor antiguo y el nuevo. Como aquí solo hay una pantalla, usamos la función especial <code>simularOtraPestana()</code> (solo existe en Xidecode) que imita a esa otra pestaña.</p>',
        parts: [
          H('<h3>Tema: <span id="tema">claro</span></h3>\n<button id="otra">Simular cambio desde otra pestaña</button>\n<ul id="registro"></ul>', 'Mostramos el tema actual, un botón que simula el cambio y un registro de eventos.'),
          J('var registro = document.getElementById("registro");\nvar tema = document.getElementById("tema");', 'Guardamos los dos elementos que vamos a modificar.'),
          J('window.addEventListener("storage", function (e) {\n  tema.textContent = e.newValue;\n  registro.innerHTML += "<li>Clave: <b>" + e.key + "</b> | antes: " + e.oldValue + " | ahora: " + e.newValue + "</li>";\n});', 'Escuchamos el evento <code>storage</code> en <code>window</code>. El parámetro <code>e</code> trae <code>key</code> (clave), <code>oldValue</code> (valor anterior) y <code>newValue</code> (valor nuevo).'),
          J('var turno = 0;\ndocument.getElementById("otra").onclick = function () {\n  turno++;\n  simularOtraPestana("tema", turno % 2 ? "oscuro" : "claro");\n};', 'Cada clic simula que otra pestaña pone el tema en "oscuro" o "claro" alternando. <code>turno % 2</code> es el resto de dividir entre 2; el operador <code>? :</code> elige entre dos valores.')
        ],
        notes: [{ type: 'warn', html: 'En un navegador real, <b>no</b> recibes el evento por tus propios cambios: solo por los que hacen <b>otras</b> pestañas. En el simulador lo imitamos porque aquí solo hay una página.' }],
        tryit: ['Haz que el registro también muestre la URL con <code>e.url</code>.', 'Cambia <code>"tema"</code> por otra clave en <code>simularOtraPestana</code>.'] }
    ],

    exercises: [
      /* X1 */
      { id: 'g8x1', title: 'Tu primer JSON: de objeto a texto', short: 'Crea un objeto y conviértelo con stringify', lib: null,
        goal: '<p>Vas a crear un objeto que describe un libro, convertirlo en texto JSON bien formateado y mostrarlo en la página.</p>',
        base: { html: '<h2>Mi libro favorito</h2>\n<pre id="resultado"></pre>', js: '// tu código aquí' },
        steps: [
          { file: 'js', title: 'Crea el objeto libro', instr: 'Declara una variable llamada <code>libro</code> con un objeto que tenga <code>titulo</code> (texto), <code>autor</code> (texto) y <code>paginas</code> (número).', why: 'Un objeto agrupa datos relacionados con pares <code>clave: valor</code> entre llaves. Los textos van entre comillas y los números no.', hint: 'Forma: <code>var libro = { titulo: "...", autor: "...", paginas: 123 };</code> Separa las propiedades con comas.', sol: 'var libro = { titulo: "Eloquent JavaScript", autor: "Marijn Haverbeke", paginas: 472 };',
            ok: /^(?:const|let|var) libro=\{(?=.*titulo:'[^']*')(?=.*autor:'[^']*')(?=.*paginas:\d+).*\}$/, errs: [[/^(?:const|let|var) libro=\{.*paginas:'\d+'/, 'Las <code>paginas</code> son un número: no lleva comillas.'], [/^libro=/, 'Falta declarar la variable con <code>var</code>, <code>let</code> o <code>const</code>.']], after: 'Ya existe el objeto <code>libro</code>.' },
          { file: 'js', type: 'blank', title: 'Conviértelo a texto', instr: 'Completa los huecos: convierte el objeto en texto JSON con <b>2 espacios</b> de sangría.', tpl: 'var texto = JSON.[[stringify]](libro, [[null]], [[2]]);', blanks: ['La función que pasa de objeto a texto empieza con "string".', 'Sin reemplazador: se escribe null.', 'Cantidad de espacios de sangría.'], why: '<code>JSON.stringify(objeto, reemplazador, separador)</code>. Como no queremos filtrar propiedades, el reemplazador es <code>null</code>; el separador <code>2</code> hace que el JSON se lea ordenado.', hint: 'La función se llama <code>stringify</code>; después del objeto van <code>null</code> y el número 2.', sol: 'var texto = JSON.stringify(libro, null, 2);', after: '<code>texto</code> ahora es un texto, no un objeto.' },
          { file: 'js', title: 'Mira el resultado en la consola', instr: 'Escribe una línea que muestre <code>texto</code> en la consola.', why: '<code>console.log</code> es tu mejor herramienta para ver qué contienen las variables. Aparece en la pestaña Consola bajo la pantalla.', hint: 'Usa <code>console.log(texto);</code>', sol: 'console.log(texto);', ok: eq('console.log(texto)'), errs: [[/^console\.log\(libro\)/, 'Eso muestra el <b>objeto</b>. Aquí queremos ver el <b>texto</b> convertido: <code>texto</code>.']] },
          { file: 'js', title: 'Comprueba el tipo', instr: 'Escribe una línea que muestre en la consola el <b>tipo</b> de <code>texto</code> usando <code>typeof</code>.', why: '<code>typeof</code> devuelve el tipo de un valor. Esperamos <code>"string"</code> (texto): la prueba de que stringify devolvió un texto y no un objeto.', hint: '<code>console.log(typeof texto);</code>', sol: 'console.log(typeof texto);', ok: eq('console.log(typeof texto)') },
          { file: 'js', title: 'Muéstralo en la página', instr: 'Escribe el texto dentro del elemento con id <code>resultado</code> usando <code>textContent</code>.', why: 'Buscamos el elemento con <code>document.getElementById</code> y cambiamos su <code>textContent</code> (texto plano). Usamos <code>textContent</code> y no <code>innerHTML</code> porque no es HTML.', hint: '<code>document.getElementById("resultado").textContent = texto;</code>', sol: 'document.getElementById("resultado").textContent = texto;', ok: /^document\.getElementById\('resultado'\)\.(?:textContent|innerText|innerHTML)=texto$/, errs: [[/getElementById\('#resultado'\)/, 'getElementById no lleva <b>#</b>: escribe solo <code>"resultado"</code>.'], [/^document\.getElementById\('resultado'\)\.(?:textContent|innerHTML)=libro$/, 'Eso escribiría el objeto. Usa la variable <code>texto</code>.']] }
        ] },
      /* X2 */
      { id: 'g8x2', title: 'Leer datos con JSON.parse', short: 'Convierte un texto JSON y usa sus propiedades', lib: null,
        goal: '<p>Recibes un texto JSON con los datos de una alumna. Vas a convertirlo en objeto, leer sus propiedades y mostrar una frase en la página.</p>',
        base: { html: '<h2>Ficha del alumno</h2>\n<p id="datos"></p>', js: 'var texto = \'{"nombre":"Marta","edad":27,"carrera":"Ingeniería"}\';\n\n// tu código aquí' },
        steps: [
          { file: 'js', title: 'Convierte el texto en objeto', instr: 'Crea la variable <code>alumno</code> con el resultado de convertir <code>texto</code> con <code>JSON.parse</code>.', why: '<code>texto</code> es un string. Hasta que no lo conviertas no puedes escribir <code>texto.nombre</code>. <code>JSON.parse</code> lo transforma en un objeto de verdad.', hint: '<code>var alumno = JSON.parse(texto);</code>', sol: 'var alumno = JSON.parse(texto);', ok: eq('var alumno=JSON.parse(texto)'), errs: [[/JSON\.stringify/, 'Esa función hace lo <b>contrario</b>: de objeto a texto. Aquí necesitas pasar de texto a objeto: <code>parse</code>.']] },
          { file: 'js', type: 'blank', title: 'Lee una propiedad', instr: 'Muestra en la consola el <b>nombre</b> del alumno.', tpl: 'console.log(alumno.[[nombre]]);', blanks: ['Es la clave que aparece en el JSON para el nombre.'], why: 'Con un objeto se lee una propiedad escribiendo punto y su nombre: <code>alumno.nombre</code>. Los nombres de propiedad son exactamente las claves del JSON.', hint: 'Mira el texto JSON de arriba: la primera clave es <code>nombre</code>.', sol: 'console.log(alumno.nombre);' },
          { file: 'js', title: 'Arma una frase', instr: 'Crea la variable <code>mensaje</code> uniendo con <code>+</code> el nombre, la edad y la carrera. Por ejemplo: <code>"Marta tiene 27 años y estudia Ingeniería"</code>, pero usando las <b>propiedades</b> del objeto, no los valores escritos a mano.', why: 'Con <code>+</code> unes textos y valores. Usar <code>alumno.nombre</code> en vez de escribir "Marta" hace que la frase se actualice sola si cambian los datos.', hint: 'Forma: <code>var mensaje = alumno.nombre + " tiene " + alumno.edad + " años y estudia " + alumno.carrera;</code>', sol: 'var mensaje = alumno.nombre + " tiene " + alumno.edad + " años y estudia " + alumno.carrera;',
            ok: function (n) { return /^(?:const|let|var) mensaje=/.test(n) && /alumno\.nombre/.test(n) && /alumno\.edad/.test(n) && /alumno\.carrera/.test(n) && !/Marta/.test(n); }, errs: [[/Marta/, 'Escribiste el nombre "a mano". Usa la propiedad <code>alumno.nombre</code> para que venga de los datos.']] },
          { file: 'js', title: 'Muéstrala en la página', instr: 'Escribe <code>mensaje</code> dentro del párrafo con id <code>datos</code>.', why: 'Igual que antes: buscar el elemento y cambiar su texto.', hint: '<code>document.getElementById("datos").textContent = mensaje;</code>', sol: 'document.getElementById("datos").textContent = mensaje;', ok: /^document\.getElementById\('datos'\)\.(?:textContent|innerText|innerHTML)=mensaje$/ },
          { file: 'js', type: 'blank', title: 'Comprueba el tipo del resultado', instr: 'Muestra en la consola de qué <b>tipo</b> es <code>alumno</code>.', tpl: 'console.log([[typeof]] alumno);', blanks: ['El operador que dice el tipo de un valor.'], why: 'Después de <code>parse</code> verás <code>"object"</code>. Antes (con <code>texto</code>) era <code>"string"</code>. Esa es la diferencia clave entre JSON (texto) y un objeto.', hint: 'El operador se escribe <code>typeof</code>.', sol: 'console.log(typeof alumno);' }
        ] },
      /* X3 */
      { id: 'g8x3', title: 'Recordar el nombre con localStorage', short: 'Guarda, lee y olvida un dato entre recargas', lib: null,
        goal: '<p>Una página que <b>recuerda tu nombre</b>: lo guardas, recargas, y sigue saludándote. Y un botón para que te olvide.</p>',
        base: { html: '<h2 id="saludo">Hola, desconocido</h2>\n<input type="text" id="nombre" placeholder="Tu nombre">\n<button id="guardar">Guardar</button>\n<button id="olvidar">Olvidar</button>', js: '// tu código aquí' },
        steps: [
          { file: 'js', title: 'Guarda el campo de texto', instr: 'Crea la variable <code>campo</code> con el elemento cuyo id es <code>nombre</code>.', why: 'Guardar elementos en variables evita buscarlos una y otra vez y hace el código más corto.', hint: '<code>var campo = document.getElementById("nombre");</code>', sol: 'var campo = document.getElementById("nombre");', ok: eq("var campo=document.getElementById('nombre')") },
          { file: 'js', title: 'Guarda el título', instr: 'Crea la variable <code>saludo</code> con el elemento cuyo id es <code>saludo</code>.', why: 'Este es el título que cambiaremos para saludar.', hint: '<code>var saludo = document.getElementById("saludo");</code>', sol: 'var saludo = document.getElementById("saludo");', ok: eq("var saludo=document.getElementById('saludo')") },
          { file: 'js', title: 'Lee lo que había guardado', instr: 'Crea la variable <code>guardado</code> leyendo del <b>localStorage</b> la clave <code>"usuario"</code>.', why: '<code>getItem(clave)</code> devuelve lo guardado o <code>null</code> si esa clave nunca se guardó. Se ejecuta cada vez que cargas la página, por eso "recuerda".', hint: '<code>var guardado = localStorage.getItem("usuario");</code>', sol: 'var guardado = localStorage.getItem("usuario");', ok: eq("var guardado=localStorage.getItem('usuario')"), errs: [[/localStorage\.setItem/, '<code>setItem</code> <b>guarda</b>. Aquí queremos <b>leer</b>: <code>getItem</code>.'], [/getitem/, 'JavaScript distingue mayúsculas: es <code>getItem</code> con la I mayúscula.']] },
          { file: 'js', title: 'Saluda si había un nombre', instr: 'Escribe un <code>if</code> que, si <code>guardado</code> <b>no es null</b>, cambie el texto de <code>saludo</code> a <code>"Hola, "</code> + el nombre.', multi: true, why: 'Si nunca guardaste nada, <code>guardado</code> es <code>null</code> y el título debe seguir diciendo "desconocido". El <code>if</code> separa los dos casos.', hint: 'if (guardado !== null) {\n  saludo.textContent = "Hola, " + guardado;\n}', sol: 'if (guardado !== null) {\n  saludo.textContent = "Hola, " + guardado;\n}', ok: function (n) { return /^if\(guardado(?:!==|!=)null\)\{/.test(n) && /saludo\.(?:textContent|innerHTML|innerText)=/.test(n) && /guardado\}?;?\}?$/.test(n) && /\}$/.test(n); }, errs: [[/^if\(guardado=null/, 'Usaste <code>=</code> (asigna). Para comparar es <code>!==</code> o <code>!=</code>.']] },
          { file: 'js', title: 'Botón Guardar', instr: 'Haz que al pulsar el botón <code>guardar</code> se guarde en localStorage el valor del campo con la clave <code>"usuario"</code> y se actualice el saludo.', multi: true, why: '<code>onclick = function () {...}</code> define lo que ocurre al hacer clic. Dentro guardamos con <code>setItem(clave, valor)</code> y mostramos el saludo para ver el cambio de inmediato.', hint: 'document.getElementById("guardar").onclick = function () {\n  localStorage.setItem("usuario", campo.value);\n  saludo.textContent = "Hola, " + campo.value;\n};', sol: 'document.getElementById("guardar").onclick = function () {\n  localStorage.setItem("usuario", campo.value);\n  saludo.textContent = "Hola, " + campo.value;\n};',
            ok: function (n) { return /^document\.getElementById\('guardar'\)\.onclick=function\(\)\{/.test(n) && /localStorage\.setItem\('usuario',campo\.value\)/.test(n) && /saludo\.(?:textContent|innerHTML|innerText)=/.test(n) && /\}$/.test(n); }, errs: [[/\.onclick=function\(\)\{.*localStorage\.setItem\('usuario'\)/, '<code>setItem</code> necesita <b>dos</b> cosas: la clave y el valor.'], [/onclick=(?!function)\w+\(\)/, 'Con <code>onclick</code> debes asignar una <b>función</b>, no el resultado de ejecutarla.']] },
          { file: 'js', title: 'Botón Olvidar', instr: 'Haz que al pulsar el botón <code>olvidar</code> se borre la clave <code>"usuario"</code> y el saludo vuelva a <code>"Hola, desconocido"</code>.', multi: true, why: '<code>removeItem(clave)</code> borra solo esa clave (a diferencia de <code>clear()</code> que borra todo el almacenamiento del sitio).', hint: 'document.getElementById("olvidar").onclick = function () {\n  localStorage.removeItem("usuario");\n  saludo.textContent = "Hola, desconocido";\n};', sol: 'document.getElementById("olvidar").onclick = function () {\n  localStorage.removeItem("usuario");\n  saludo.textContent = "Hola, desconocido";\n};',
            ok: function (n) { return /^document\.getElementById\('olvidar'\)\.onclick=function\(\)\{/.test(n) && /localStorage\.removeItem\('usuario'\)/.test(n) && /saludo\.(?:textContent|innerHTML|innerText)='Hola,desconocido'/.test(n) && /\}$/.test(n); }, errs: [[/localStorage\.clear\(\)/, '<code>clear()</code> borraría <b>todo</b>. Para borrar solo una clave usa <code>removeItem("usuario")</code>.']] }
        ], final: 'Prueba: escribe tu nombre, pulsa Guardar y luego el botón <b>Recargar</b> de la computadora. ¡Sigue saludándote! Mira la pestaña Almacenamiento.' },
      /* X4 */
      { id: 'g8x4', title: 'Lista de tareas que no se pierde', short: 'Guarda un arreglo con stringify y recupéralo con parse', lib: null,
        goal: '<p>Una lista de tareas cuyo contenido <b>se conserva</b> al recargar. Es el momento de usar <code>JSON.stringify</code> y <code>JSON.parse</code> con un arreglo.</p>',
        base: { html: '<h2>Mis tareas</h2>\n<input type="text" id="tarea" placeholder="Nueva tarea">\n<button id="agregar">Agregar</button>\n<ul id="lista"></ul>', js: '// tu código aquí' },
        steps: [
          { file: 'js', title: 'Recupera las tareas guardadas', instr: 'Crea el arreglo <code>tareas</code> con lo que haya en localStorage bajo la clave <code>"tareas"</code> (convertido con <code>JSON.parse</code>), o con un <b>arreglo vacío</b> si no hay nada.', why: 'En localStorage solo hay texto. <code>JSON.parse</code> lo vuelve a convertir en arreglo. Si la clave no existe, <code>getItem</code> da <code>null</code> y <code>JSON.parse(null)</code> da <code>null</code>; el <code>|| []</code> ("o si no, un arreglo vacío") nos protege.', hint: '<code>var tareas = JSON.parse(localStorage.getItem("tareas")) || [];</code>', sol: 'var tareas = JSON.parse(localStorage.getItem("tareas")) || [];', ok: eq("var tareas=JSON.parse(localStorage.getItem('tareas'))||[]"), errs: [[/^(?:const|let|var) tareas=localStorage\.getItem/, 'Eso te da un <b>texto</b>, no un arreglo. Envuélvelo con <code>JSON.parse( ... )</code>.']] },
          { file: 'js', title: 'Abre la función dibujar', instr: 'Escribe la primera línea de la función <code>dibujar</code> (sin parámetros).', why: 'Cada vez que cambie la lista vamos a volver a pintarla. Una función nos deja repetir ese trabajo con una sola llamada.', hint: '<code>function dibujar() {</code>', sol: 'function dibujar() {', ok: eq('function dibujar(){') },
          { file: 'js', indent: 1, title: 'Limpia la lista', instr: 'Dentro de la función, guarda el <code>ul</code> de id <code>lista</code> en la variable <code>ul</code> y vacíalo con <code>innerHTML = ""</code>. (Dos líneas.)', multi: true, why: 'Antes de pintar hay que vaciar la lista; si no, cada vez se repetirían los elementos anteriores.', hint: 'var ul = document.getElementById("lista");\nul.innerHTML = "";', sol: 'var ul = document.getElementById("lista");\nul.innerHTML = "";', ok: function (n) { return /^(?:const|let|var) ul=document\.getElementById\('lista'\);ul\.innerHTML=''$/.test(n); } },
          { file: 'js', indent: 1, title: 'Recorre las tareas', instr: 'Con un bucle <code>for</code> sobre <code>tareas</code>, agrega a <code>ul.innerHTML</code> un <code>&lt;li&gt;</code> por cada tarea (usa <code>+=</code>).', multi: true, why: '<code>tareas[i]</code> es la tarea en la posición <code>i</code>. Con <code>+=</code> vamos <b>acumulando</b> HTML en lugar de reemplazarlo.', hint: 'for (var i = 0; i < tareas.length; i++) {\n  ul.innerHTML += "<li>" + tareas[i] + "</li>";\n}', sol: 'for (var i = 0; i < tareas.length; i++) {\n  ul.innerHTML += "<li>" + tareas[i] + "</li>";\n}', ok: function (n) { return /^for\(var i=0;i<tareas\.length;i\+\+\)\{ul\.innerHTML\+=('<li>'\+tareas\[i\]\+'<\/li>')\}$/.test(n) || /^for\((?:var|let) (\w)=0;\1<tareas\.length;\1\+\+\)\{ul\.innerHTML\+='<li>'\+tareas\[\1\]\+'<\/li>'\}$/.test(n); }, errs: [[/ul\.innerHTML=/, 'Con <code>=</code> reemplazas todo en cada vuelta y solo quedaría la última tarea. Usa <code>+=</code> para acumular.']] },
          { file: 'js', title: 'Cierra la función', instr: 'Cierra la función con una llave.', why: 'Cada <code>{</code> necesita su <code>}</code>. Esta cierra el bloque de <code>function dibujar()</code>.', hint: 'Solo el símbolo <code>}</code>', sol: '}', ok: /^\}$/ },
          { file: 'js', title: 'Pinta al cargar', instr: 'Llama a la función <code>dibujar</code> para que se muestren las tareas guardadas al abrir la página.', why: 'Definir una función no la ejecuta: hay que llamarla con paréntesis.', hint: '<code>dibujar();</code>', sol: 'dibujar();', ok: eq('dibujar()') },
          { file: 'js', title: 'Botón Agregar', instr: 'Escribe el manejador del botón <code>agregar</code>: agrega el texto del campo a <code>tareas</code> con <code>push</code>, guarda el arreglo con <code>JSON.stringify</code>, vuelve a dibujar y vacía el campo.', multi: true, why: 'El orden importa: 1) <code>push</code> modifica el arreglo, 2) <code>stringify</code> + <code>setItem</code> lo guarda en el navegador, 3) <code>dibujar()</code> actualiza la pantalla. Sin el paso 2, al recargar se perdería.', hint: 'document.getElementById("agregar").onclick = function () {\n  var campo = document.getElementById("tarea");\n  tareas.push(campo.value);\n  localStorage.setItem("tareas", JSON.stringify(tareas));\n  dibujar();\n  campo.value = "";\n};', sol: 'document.getElementById("agregar").onclick = function () {\n  var campo = document.getElementById("tarea");\n  tareas.push(campo.value);\n  localStorage.setItem("tareas", JSON.stringify(tareas));\n  dibujar();\n  campo.value = "";\n};',
            ok: function (n) { return /^document\.getElementById\('agregar'\)\.onclick=function\(\)\{/.test(n) && /tareas\.push\(/.test(n) && /localStorage\.setItem\('tareas',JSON\.stringify\(tareas\)\)/.test(n) && /dibujar\(\)/.test(n) && /\}$/.test(n); }, errs: [[/localStorage\.setItem\('tareas',tareas\)/, 'Así se guardaría <code>"[object Object]"</code>/texto sin formato. Convierte el arreglo: <code>JSON.stringify(tareas)</code>.']] }
        ], final: 'Agrega varias tareas y pulsa <b>Recargar</b> en la computadora: la lista reaparece. Mira en la pestaña Almacenamiento cómo se ve el arreglo guardado como texto JSON.' },
      /* X5 */
      { id: 'g8x5', title: 'Autoguardado de un formulario', short: 'Guarda cada 3 segundos y restaura al recargar', lib: null,
        goal: '<p>Es el ejercicio del <b>análisis de resultados</b> de la guía: un formulario que se <b>autoguarda cada 3 segundos</b> para no perder lo escrito si la página se recarga. Al terminar, cambia <code>localStorage</code> por <code>sessionStorage</code> y compara.</p>',
        base: { html: '<h3>Formulario con autoguardado</h3>\n<input type="text" id="nombre" placeholder="Nombre completo"><br><br>\n<select id="pais">\n  <option>Guatemala</option><option>El Salvador</option><option>Honduras</option>\n  <option>Nicaragua</option><option>Costa Rica</option><option>Panamá</option>\n</select><br><br>\n<textarea id="bio" rows="3" cols="30" placeholder="Pequeña biografía"></textarea>\n<p id="estado" style="color:#2f8f4e"></p>', js: '// tu código aquí' },
        steps: [
          { file: 'js', title: 'Lista de campos', instr: 'Crea el arreglo <code>campos</code> con los ids de los tres campos: <code>"nombre"</code>, <code>"pais"</code> y <code>"bio"</code>.', why: 'Si guardamos los ids en una lista podremos recorrerla con un bucle en lugar de repetir código para cada campo.', hint: '<code>var campos = ["nombre", "pais", "bio"];</code>', sol: 'var campos = ["nombre", "pais", "bio"];', ok: eq("var campos=['nombre','pais','bio']") },
          { file: 'js', title: 'Abre la función guardar', instr: 'Escribe la primera línea de la función <code>guardar</code>.', why: 'Esta función se ejecutará cada 3 segundos.', hint: '<code>function guardar() {</code>', sol: 'function guardar() {', ok: eq('function guardar(){') },
          { file: 'js', indent: 1, title: 'Junta los valores en un objeto', instr: 'Crea un objeto vacío <code>datos</code> y con un bucle <code>for</code> guarda en él el valor de cada campo: <code>datos[campos[i]] = ...value</code>.', multi: true, why: 'La notación de corchetes <code>datos[clave]</code> permite usar un nombre que está en una variable. Así <code>datos["nombre"]</code>, <code>datos["pais"]</code>... se llenan con el mismo código.', hint: 'var datos = {};\nfor (var i = 0; i < campos.length; i++) {\n  datos[campos[i]] = document.getElementById(campos[i]).value;\n}', sol: 'var datos = {};\nfor (var i = 0; i < campos.length; i++) {\n  datos[campos[i]] = document.getElementById(campos[i]).value;\n}', ok: function (n) { return /^(?:const|let|var) datos=\{\};for\(var i=0;i<campos\.length;i\+\+\)\{datos\[campos\[i\]\]=document\.getElementById\(campos\[i\]\)\.value\}$/.test(n); } },
          { file: 'js', indent: 1, title: 'Guárdalo en el almacenamiento', instr: 'Guarda <code>datos</code> convertido a texto en localStorage con la clave <code>"borrador"</code>.', why: '<code>datos</code> es un objeto, así que hay que usar <code>JSON.stringify</code> antes de <code>setItem</code>.', hint: '<code>localStorage.setItem("borrador", JSON.stringify(datos));</code>', sol: 'localStorage.setItem("borrador", JSON.stringify(datos));', ok: eq("localStorage.setItem('borrador',JSON.stringify(datos))"), errs: [[/setItem\('borrador',datos\)/, 'Falta convertir el objeto a texto con <code>JSON.stringify(datos)</code>.']] },
          { file: 'js', indent: 1, title: 'Avisa al usuario', instr: 'Escribe en el párrafo <code>estado</code> el texto <code>"Guardado automáticamente"</code>.', why: 'Un mensaje confirma que el autoguardado funciona.', hint: '<code>document.getElementById("estado").textContent = "Guardado automáticamente";</code>', sol: 'document.getElementById("estado").textContent = "Guardado automáticamente";', ok: /^document\.getElementById\('estado'\)\.(?:textContent|innerText|innerHTML)='Guardado automáticamente'$/ },
          { file: 'js', title: 'Cierra la función', instr: 'Cierra la función <code>guardar</code>.', why: 'Cierra el bloque abierto con <code>{</code>.', hint: '<code>}</code>', sol: '}', ok: /^\}$/ },
          { file: 'js', title: 'Restaura al cargar', instr: 'Lee <code>"borrador"</code> con <code>JSON.parse</code> y, si existe, recorre <code>campos</code> y pon cada valor en su campo.', multi: true, why: 'Al abrir la página recuperamos el objeto guardado y repartimos sus valores en los campos. El <code>if (borrador)</code> evita errores si todavía no hay nada guardado.', hint: 'var borrador = JSON.parse(localStorage.getItem("borrador"));\nif (borrador) {\n  for (var i = 0; i < campos.length; i++) {\n    document.getElementById(campos[i]).value = borrador[campos[i]];\n  }\n}', sol: 'var borrador = JSON.parse(localStorage.getItem("borrador"));\nif (borrador) {\n  for (var i = 0; i < campos.length; i++) {\n    document.getElementById(campos[i]).value = borrador[campos[i]];\n  }\n}', ok: function (n) { return /^(?:const|let|var) borrador=JSON\.parse\(localStorage\.getItem\('borrador'\)\);if\(borrador\)\{for\(var i=0;i<campos\.length;i\+\+\)\{document\.getElementById\(campos\[i\]\)\.value=borrador\[campos\[i\]\]\}\}$/.test(n); } },
          { file: 'js', title: 'Autoguardado cada 3 segundos', instr: 'Haz que <code>guardar</code> se ejecute automáticamente cada 3000 milisegundos.', why: '<code>setInterval(funcion, milisegundos)</code> repite una función. Pasa <code>guardar</code> <b>sin paréntesis</b> (la función, no su resultado).', hint: '<code>setInterval(guardar, 3000);</code>', sol: 'setInterval(guardar, 3000);', ok: eq('setInterval(guardar,3000)'), errs: [[/setInterval\(guardar\(\)/, 'Con paréntesis ejecutarías <code>guardar</code> una sola vez. Pásala sin paréntesis.'], [/setTimeout/, '<code>setTimeout</code> espera y se ejecuta <b>una sola vez</b>. Para repetir cada cierto tiempo usa <code>setInterval</code>.']] }
        ], final: 'Escribe algo, espera 3 segundos (aparece el aviso) y pulsa <b>Recargar</b>: tus datos regresan. Ahora cambia <code>localStorage</code> por <code>sessionStorage</code> en las líneas del código (modo libre) y prueba <b>Cerrar pestaña</b>.' }
    ],

    quiz: [
      { q: '¿Cuál de estos textos es un JSON <b>válido</b>?', opts: ['{ nombre: "Ana" }', '{"nombre": \'Ana\'}', '{"nombre": "Ana"}', '{"nombre": "Ana",}'], a: 2, why: 'Solo el tercero usa comillas dobles en la clave y en el texto y no tiene coma sobrante.' },
      { q: 'Tienes un <b>objeto</b> y quieres guardarlo en localStorage. ¿Qué haces primero?', opts: ['Usar JSON.parse(objeto)', 'Usar JSON.stringify(objeto)', 'Nada, localStorage guarda objetos', 'Usar sessionStorage'], a: 1, why: 'localStorage solo guarda texto. <code>JSON.stringify</code> convierte el objeto en texto.' },
      { q: 'Si pides con <code>getItem</code> una clave que <b>no existe</b>, ¿qué devuelve?', opts: ['undefined', 'Un texto vacío ""', 'null', 'Lanza un error'], a: 2, why: '<code>getItem</code> devuelve <code>null</code> cuando la clave no existe.' },
      { q: '¿Qué diferencia hay entre localStorage y sessionStorage?', opts: ['No hay diferencia', 'sessionStorage se borra al cerrar la pestaña; localStorage no caduca', 'localStorage se borra al cerrar la pestaña', 'sessionStorage guarda más datos'], a: 1, why: 'localStorage persiste hasta que se borre; sessionStorage vive solo mientras esa pestaña esté abierta.' },
      { q: 'Ejecutas <code>localStorage.setItem("n", 5);</code>. ¿Qué tipo tiene <code>localStorage.getItem("n")</code>?', opts: ['number', 'string', 'object', 'boolean'], a: 1, why: 'Todo se guarda y se lee como <b>texto</b>. Para calcular, conviértelo con <code>Number()</code> o <code>parseInt()</code>.' },
      { q: '¿Qué hace este código?', code: 'var o = JSON.parse(\'{"a":1}\');\nconsole.log(o.a + 1);', opts: ['Muestra "11"', 'Muestra 2', 'Lanza un error', 'Muestra "a1"'], a: 1, why: '<code>parse</code> crea un objeto con <code>a</code> numérico (1), así que <code>1 + 1</code> es <b>2</b>.' },
      { q: 'Quieres recorrer todo lo guardado. ¿Qué usas?', opts: ['localStorage.length y localStorage.key(i)', 'localStorage.all()', 'JSON.keys(localStorage)', 'localStorage.forEach'], a: 0, why: '<code>length</code> dice cuántos datos hay y <code>key(i)</code> da el nombre de cada clave.' },
      { q: '¿Cuándo se dispara el evento <code>storage</code> de <code>window</code>?', opts: ['Cuando tu misma pestaña guarda un dato', 'Cuando OTRA pestaña del mismo sitio cambia el almacenamiento', 'Cada segundo', 'Al cargar la página'], a: 1, why: 'El evento avisa a las demás pestañas del mismo sitio; la que hizo el cambio no lo recibe.' }
    ]
  });
})();
